// Generated by `npm run toolkits:sync` in the CMS repository (toolkits/client). Do not edit here.
import type { WebhookPayload } from "./types";

// Webhook signatures (cms/docs/API.md): x-cms-timestamp is unix seconds and
// x-cms-signature is hex HMAC-SHA256 of `${timestamp}.${rawBody}` with the
// webhook secret. Built on WebCrypto, so it runs in Node 20+, edge runtimes
// and workers alike. The build-status report to the CMS is signed the same way.

export const SIGNATURE_WINDOW_MS = 5 * 60_000;

const encoder = new TextEncoder();

/** The hex HMAC-SHA256 of `payload` with `secret`. */
export async function hmacSha256(secret: string, payload: string) {
  const key = await crypto.subtle.importKey("raw", encoder.encode(secret), { name: "HMAC", hash: "SHA-256" }, false, ["sign"]);
  const bytes = new Uint8Array(await crypto.subtle.sign("HMAC", key, encoder.encode(payload)));
  return Array.from(bytes, (b) => b.toString(16).padStart(2, "0")).join("");
}

/** Compares two strings in time that depends only on their length, never on where they differ. */
export function safeEqual(a: string, b: string) {
  const left = encoder.encode(a);
  const right = encoder.encode(b);
  // A length mismatch still walks the longer input so the duration gives nothing away.
  const length = Math.max(left.length, right.length);
  let diff = left.length ^ right.length;
  for (let i = 0; i < length; i++) diff |= (left[i] ?? 0) ^ (right[i] ?? 0);
  return diff === 0;
}

/** Signs a body the way the CMS expects (and the way it signs its own calls). */
export async function signBody(body: string, secret: string, now = Date.now()) {
  const timestamp = Math.floor(now / 1000).toString();
  return { timestamp, signature: await hmacSha256(secret, `${timestamp}.${body}`) };
}

type HeaderSource = Headers | Record<string, string | string[] | undefined> | { get(name: string): string | null | undefined };

function header(headers: HeaderSource, name: string): string {
  if (typeof (headers as { get?: unknown }).get === "function") return (headers as { get(name: string): string | null | undefined }).get(name) ?? "";
  const record = headers as Record<string, string | string[] | undefined>;
  const key = Object.keys(record).find((k) => k.toLowerCase() === name);
  const value = key ? record[key] : undefined;
  return Array.isArray(value) ? (value[0] ?? "") : (value ?? "");
}

export type VerifyResult = { ok: true; event: string; payload: WebhookPayload } | { ok: false; reason: "missing_secret" | "missing_headers" | "stale_timestamp" | "bad_signature" | "bad_json" };

/**
 * Verifies a webhook delivery. `rawBody` must be the body exactly as received
 * (not re-serialized JSON). The timestamp may not be older or newer than five
 * minutes unless `toleranceMs` says otherwise.
 */
export async function verifyWebhook(rawBody: string, headers: HeaderSource, secret: string, options: { now?: number; toleranceMs?: number } = {}): Promise<VerifyResult> {
  if (!secret) return { ok: false, reason: "missing_secret" };
  const timestamp = header(headers, "x-cms-timestamp");
  const signature = header(headers, "x-cms-signature");
  if (!/^\d{10}$/.test(timestamp) || !signature) return { ok: false, reason: "missing_headers" };
  const now = options.now ?? Date.now();
  if (Math.abs(now - Number(timestamp) * 1000) > (options.toleranceMs ?? SIGNATURE_WINDOW_MS)) return { ok: false, reason: "stale_timestamp" };
  const expected = await hmacSha256(secret, `${timestamp}.${rawBody}`);
  if (!safeEqual(signature.toLowerCase(), expected)) return { ok: false, reason: "bad_signature" };
  let payload: WebhookPayload;
  try {
    payload = JSON.parse(rawBody) as WebhookPayload;
  } catch {
    return { ok: false, reason: "bad_json" };
  }
  return { ok: true, event: header(headers, "x-cms-event") || payload.event, payload };
}

/** The events inside a delivery: the one event, or every event of a batch. */
export function eventsOf(payload: WebhookPayload) {
  if (payload.event === "batch") return payload.events.map((e) => ({ event: e.event, data: e.data }));
  return [{ event: payload.event, data: payload.data }];
}

/** Every cache tag the delivery touches (deduplicated), from `data.tags` plus the type/entry pair when the server sent none. */
export function tagsOf(payload: WebhookPayload) {
  const tags = new Set<string>();
  for (const { event, data } of eventsOf(payload)) {
    for (const tag of data.tags ?? []) tags.add(tag);
    if (!data.tags) {
      if (event.startsWith("entry.") && typeof data.type === "string") tags.add(`type:${data.type}`);
      if (event.startsWith("entry.") && typeof data.documentId === "string") tags.add(`entry:${data.documentId}`);
      if (event === "menu.updated") tags.add("menus");
      if (event === "settings.updated") tags.add("settings");
      if (event === "schema.updated") tags.add("schema");
      if (event === "taxonomy.updated" && typeof data.taxonomy === "string") tags.add(`taxonomy:${data.taxonomy}`);
      if (event.startsWith("asset.") && typeof data.id === "string") tags.add(`asset:${data.id}`);
    }
  }
  return [...tags];
}

/** Every public path the delivery names (deduplicated). */
export function pathsOf(payload: WebhookPayload) {
  return [...new Set(eventsOf(payload).flatMap(({ data }) => data.paths ?? []))];
}

/** The type apiIds a delivery touches, read from `type:<apiId>` tags. */
export const typesOf = (payload: WebhookPayload) => tagsOf(payload).filter((t) => t.startsWith("type:")).map((t) => t.slice(5));
